let currentPage = 'home';
let currentSession = CONFIG.currentSession;

function navigate(pageName, sessionNum) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-link').forEach(a => a.classList.remove('active'));
  const page = document.getElementById('page-' + pageName);
  if (page) page.classList.add('active');
  const navLink = document.querySelector(`[data-page="${pageName}"]`);
  if (navLink) navLink.classList.add('active');
  document.getElementById('mainNav').classList.remove('open');
  currentPage = pageName;
  window.scrollTo(0, 0);
  switch (pageName) {
    case 'home':      renderDashboard(); break;
    case 'guide':     renderGuide(); break;
    case 'lectures':  renderLectures(sessionNum !== undefined ? sessionNum : currentSession); break;
    case 'mission':   renderMission(); break;
    case 'submit':    renderSubmit(); break;
    case 'status':    renderStatus(); break;
    case 'resources': renderResources(); break;
    case 'notices':   renderNotices(); break;
  }
}

function goToLecture(num) { currentSession = num; navigate('lectures', num); }
function goToMissionCert() { window.open(CONFIG.naverCafeUrl, '_blank'); }
function goToSubmit() { goToMissionCert(); }

