// ─── 유틸리티 ───
function getEmbedUrl(url) {
  if (!url || url.trim() === '') return null;
  if (url.includes('youtube.com/watch')) {
    try { const v = new URL(url).searchParams.get('v'); return `https://www.youtube.com/embed/${v}`; } catch(e){ return null; }
  }
  if (url.includes('youtu.be/')) return `https://www.youtube.com/embed/${url.split('youtu.be/')[1].split('?')[0]}`;
  if (url.includes('youtube.com/embed/')) return url;
  if (url.includes('drive.google.com/file/d/')) {
    const m = url.match(/\/d\/([a-zA-Z0-9_-]+)/);
    if (m) return `https://drive.google.com/file/d/${m[1]}/preview`;
  }
  return url;
}

function getStatusColor(status) {
  const map = {
    "입장 완료":           { bg: "#F0F0F0", text: "#666" },
    "1차 완료":            { bg: "#FFF3E0", text: "#E65100" },
    "2차 완료":            { bg: "#FFF8E1", text: "#F57F17" },
    "3차 완료":            { bg: "#F3E5F5", text: "#6A1B9A" },
    "4차 완료":            { bg: "#E8EAF6", text: "#283593" },
    "5차 완료":            { bg: "#E3F2FD", text: "#1565C0" },
    "6차 완료":            { bg: "#E0F2F1", text: "#00695C" },
    "7차 완료(원고 완성)": { bg: "#E8F5E9", text: "#1B5E20" },
    "8차 완료":            { bg: "#FCE4EC", text: "#880E4F" },
    "9차 완료":            { bg: "#F3E5F5", text: "#4A148C" },
    "10차 완료":           { bg: "#FF6B2C", text: "#FFFFFF" }
  };
  return map[status] || { bg: "#F0F0F0", text: "#444" };
}

function nl2br(str) { return str.replace(/\n/g, '<br>'); }

// ─── 진행 바 ───
function buildProgressBar(activeSession) {
  const phase1 = [1,2,3,4,5,6,7];
  const phase2 = [8,9,10];
  const makeDot = (num) => {
    let cls = 'progress-dot';
    if (num < activeSession) cls += ' done';
    if (num === activeSession) cls += ' current';
    const inner = num < activeSession ? '✓' : (num === activeSession ? '●' : '');
    return `<div class="progress-step"><div class="${cls}">${inner}</div><span class="progress-label">${num}차</span></div>`;
  };
  const dots1 = phase1.map((n,i) => (i>0?'<div class="progress-line"></div>':'')+makeDot(n)).join('');
  const dots2 = phase2.map((n,i) => (i>0?'<div class="progress-line"></div>':'')+makeDot(n)).join('');
  return `<div class="week-progress-wrap">
    <div class="week-progress">
      ${dots1}
      <div class="progress-divider">|</div>
      ${dots2}
    </div>
    <p class="progress-caption">
      1~7차: ${CONFIG.orientationDate} OT 후 6/1~6/25 목표
      &nbsp;·&nbsp;
      <span style="color:#888">8~10차: 7차 원고 완성 후 추천</span>
    </p>
  </div>`;
}

// ─── 영상 영역 ───
function buildVideoArea(videoUrl, title, missionUrl) {
  // naver.me 링크는 iframe 임베드 불가 → 외부 링크 버튼으로 표시
  if (videoUrl && videoUrl.includes('naver.me')) {
    return `<div class="video-link-box">
      <div class="video-link-icon">▶</div>
      <p class="video-link-title">${title} 강의</p>
      <a href="${videoUrl}" target="_blank" class="btn btn-orange video-link-btn">📺 강의 보러 가기 →</a>
    </div>`;
  }
  const embedUrl = getEmbedUrl(videoUrl);
  if (embedUrl) {
    return `<div class="video-container">
      <iframe src="${embedUrl}" frameborder="0" allowfullscreen
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"></iframe>
    </div>`;
  }
  const noticeUrl = missionUrl || CONFIG.naverMissionUrl;
  return `<div class="video-placeholder">
    <div class="video-placeholder-icon">▶</div>
    <p class="video-placeholder-title">${title} 강의 영상</p>
    <p class="video-placeholder-desc">강의 영상이 업로드되면 여기서 바로 볼 수 있어요.</p>
    <a href="${noticeUrl}" target="_blank"
       style="display:inline-block;margin-top:12px;background:#FF6B2C;color:#fff;font-size:13px;font-weight:700;padding:8px 18px;border-radius:20px;text-decoration:none;">
      📌 네이버 카페 미션 공지사항 확인하기
    </a>
  </div>`;
}

// ─── 미션 목록 ───
function buildMissionList(missions) {
  return missions.map((m, i) =>
    `<div class="mission-item">
      <span class="mission-num">${i+1}</span>
      <span class="mission-text">${m}</span>
    </div>`
  ).join('');
}

// ─── 자료 목록 (url 없으면 카페 참고자료 게시판으로 연결) ───
function buildResourceList(resources) {
  return resources.map(r => {
    // 로컬 파일(./) → 오버레이로 열기
    if (r.url && r.url.startsWith('./')) {
      const key = r.url.replace('./', '').replace('.html', '');
      return '<div class="resource-item">' +
        '<span class="resource-name" style="cursor:pointer;" onclick="openOverlay(\'' + key + '\')">' + r.name + '</span>' +
        '<button onclick="openOverlay(\'' + key + '\')" class="resource-badge ready">열기 →</button>' +
        '</div>';
    }
    if (r.url && r.url.trim() !== '') {
      return '<div class="resource-item">' +
        '<a href="' + r.url + '" target="_blank" class="resource-name">' + r.name + '</a>' +
        '<a href="' + r.url + '" target="_blank" class="resource-badge ready">다운로드 ↓</a>' +
        '</div>';
    }
    return '<div class="resource-item">' +
      '<a href="' + CONFIG.naverResourceUrl + '" target="_blank" class="resource-name">' + r.name + '</a>' +
      '<a href="' + CONFIG.naverResourceUrl + '" target="_blank" class="resource-badge ready">카페에서 보기 →</a>' +
      '</div>';
  }).join('');
}

// ─── FAQ ───
function buildFAQ(faqItems) {
  return faqItems.map((item, i) =>
    `<div class="faq-item" id="faq-${i}">
      <button class="faq-q" onclick="toggleFAQ(${i})">
        <span>Q. ${item.q}</span><span class="faq-arrow">▼</span>
      </button>
      <div class="faq-a" id="faq-a-${i}"><p>A. ${item.a}</p></div>
    </div>`
  ).join('');
}

function toggleFAQ(i) {
  const answer = document.getElementById('faq-a-' + i);
  const arrow = document.querySelector(`#faq-${i} .faq-arrow`);
  const isOpen = answer.classList.contains('open');
  answer.classList.toggle('open', !isOpen);
  if (arrow) arrow.textContent = isOpen ? '▼' : '▲';
}

