// ─ 샘플 이미지 ─
var SAMPLE_EBOOK_IMG = 'data:image/png;base64,';

function openOverlay(key) {
  if (!document.getElementById('ov-styles')) {
    var s = document.createElement('style');
    s.id = 'ov-styles';
    s.textContent = getOvStyles();
    document.head.appendChild(s);
  }
  var map = {
    'checklist-draft':          getChecklistContent,
    'worksheet-plan':           getPlanContent,
    'worksheet-target-reader':  getTargetContent
  };
  var fn = map[key];
  if (!fn) return;
  document.getElementById('overlayContent').innerHTML = fn();
  document.getElementById('overlayPanel').classList.add('open');
  document.body.style.overflow = 'hidden';
}

function closeOverlay() {
  document.getElementById('overlayPanel').classList.remove('open');
  document.body.style.overflow = '';
}

