// ─ 체크리스트 인터랙션 ─
function toggleCheck(el) {
  el.classList.toggle('checked');
  _updateClProgress();
  document.getElementById('cl-complete') && document.getElementById('cl-complete').classList.remove('show');
  document.getElementById('cl-partial')  && document.getElementById('cl-partial').classList.remove('show');
}
function _updateClProgress() {
  var items   = document.querySelectorAll('#overlayContent .ov-check');
  var checked = document.querySelectorAll('#overlayContent .ov-check.checked').length;
  var total   = items.length;
  var pct = total ? Math.round(checked/total*100) : 0;
  var fill = document.getElementById('cl-fill');
  var text = document.getElementById('cl-text');
  if (fill) fill.style.width = pct + '%';
  if (text) text.textContent = checked + ' / ' + total + ' 완료';
}
function checkClResult() {
  var items   = document.querySelectorAll('#overlayContent .ov-check');
  var checked = document.querySelectorAll('#overlayContent .ov-check.checked').length;
  var total   = items.length;
  var comp = document.getElementById('cl-complete');
  var part = document.getElementById('cl-partial');
  comp && comp.classList.remove('show');
  part && part.classList.remove('show');
  setTimeout(function() {
    if (checked === total) {
      comp && comp.classList.add('show');
      comp && comp.scrollIntoView({behavior:'smooth', block:'center'});
    } else {
      part && part.classList.add('show');
      part && part.scrollIntoView({behavior:'smooth', block:'center'});
    }
  }, 100);
}
function resetChecklist() {
  document.querySelectorAll('#overlayContent .ov-check').forEach(function(el){ el.classList.remove('checked'); });
  document.getElementById('cl-complete') && document.getElementById('cl-complete').classList.remove('show');
  document.getElementById('cl-partial')  && document.getElementById('cl-partial').classList.remove('show');
  _updateClProgress();
}

// ─ 워크시트 인터랙션 ─
function toggleBenchmark(show) {
  var el = document.getElementById('bm-wrap');
  if (el) el.style.display = show ? 'block' : 'none';
}
function showPlanSummary() {
  function g(id){ var el=document.getElementById(id); return el&&el.value.trim()||'—'; }
  var card = document.getElementById('plan-sum');
  if (!card) return;
  ['what','why','who','how','ptype','extras','psum'].forEach(function(k){
    var el = document.getElementById('ps-'+k);
    if(el) el.textContent = g('p-'+k);
  });
  card.style.display = 'block';
  card.scrollIntoView({behavior:'smooth', block:'start'});
}
function showTargetSummary() {
  function g(id){ var el=document.getElementById(id); return el&&el.value.trim()||'—'; }
  var card = document.getElementById('tgt-sum');
  if (!card) return;
  var age = g('t-age'); var gen = g('t-gender');
  document.getElementById('ts-age').textContent = age + (gen !== '—' ? ' / ' + gen : '');
  ['job','lifestyle','problem','desire','value','summary'].forEach(function(k){
    var el = document.getElementById('ts-'+k);
    if(el) el.textContent = g('t-'+k);
  });
  card.style.display = 'block';
  card.scrollIntoView({behavior:'smooth', block:'start'});
}

